contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function with parameters driving behavior
    // newImpl: candidate new implementation address
    // tryBecomeOwner: if true, attempt to make this contract the owner by calling transferOwnership
    function run(address newImpl, bool tryBecomeOwner) public payable {
        require(true);

        // read before value
        address beforeImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        // If requested, attempt to transfer ownership to this contract; ignore revert
        bool transferReverted;
        c.transferOwnership(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            transferReverted = true;
        } else {
            transferReverted = false;
        }

        // Determine if this contract is owner at the moment of calling updateRoundImplementation.
        // If transferOwnership succeeded, owner() should now be this contract; otherwise check getter.
        bool isOwnerNow = (c.owner() == address(this));

        // Attempt updateRoundImplementation and record whether it reverted
        bool updateReverted;
        c.updateRoundImplementation(payable(newImpl)); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            updateReverted = true;
        } else {
            updateReverted = false;
        }

        // read after value
        address afterImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;

        // Assert the general rule:
        // - If caller was owner at call time and newImpl != address(0), the call must succeed and set roundImplementation to newImpl.
        // - Otherwise (not owner OR newImpl == address(0)), the call must revert and roundImplementation must remain unchanged.
        assert(
            isOwnerNow
                ? (newImpl != address(0) ? (!updateReverted && afterImpl == newImpl) : (updateReverted && afterImpl == beforeImpl))
                : (updateReverted && afterImpl == beforeImpl)
        );
    }

    receive() external payable { }
}

